('{"id":"AGRO-SOJ-0070","kb":"expandida","area":"AGRO","area_name":"Agronegócio","subcategory":"Soja","canonical_question":"Onde estão os principais bancos de germoplasma de soja no mundo?","answer":"Os principais bancos de germoplasma de soja estão nos Estados Unidos, na China e no Brasil.","kind":"conceito","status":"confirmado","as_of":"2019","edition_number":null,"edition_year":null,"dynamic_instructions":null,"citation_template":null,"sources":[{"title":"Embrapa – Soja: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2019), pergunta 70","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/1118408/2/500PERGUNTASSojaed012019.pdf","accessed":"2026-10-17","publisher":"Embrapa","item":70,"label":"Embrapa – Soja: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2019), pergunta 70"},{"title":"Infoteca-e Embrapa – registro do livro \"Soja: o produtor pergunta, a Embrapa responde\"","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/handle/doc/1118408","accessed":"2026-10-17","label":"Infoteca-e Embrapa – registro do livro \"Soja: o produtor pergunta, a Embrapa responde\""}],"tags":["soja"],"related_ids":["AGRO-SOJ-0071"],"fenasoja_links":[],"gaps":[],"relevance":"alta","priority":2,"kb_version":"2026-10-17","context":{"scope":"general","subject":"agriculture","reference_period":null,"valid_from":null,"valid_until":null,"edition_required":false},"public_notes":["Referência: publicação da Embrapa de 2019. Informações técnicas, produtos, cultivares e números podem estar desatualizados."],"query_policy":{"collision_groups":[],"preference_rank":1},"editorial_metadata":{"area":"AGRO","area_nome":"Agronegócio","subcategoria":"Soja","interpretation_notes":"Resposta resumida do item nº 70 do livro da Embrapa \"Soja: o produtor pergunta, a Embrapa responde\" (2019).","kind":"conceito","status":"confirmado","as_of":"2019","relevancia_fenasoja":"alta","fenasoja_kb_links":[],"n_perguntas":4,"fonte_tipo":