('{"id":"AGTECH-GEO-0195","kb":"expandida","area":"AGTECH","area_name":"Inovação e agtech","subcategory":"Geotecnologias e agricultura de precisão","canonical_question":"Qual a importância do Sistema de Informação Geográfica (SIG) em agrometeorologia?","answer":"Geralmente, o SIG é uma ferramenta de geoprocessamento que permite o armazenamento, a recuperação, a manipulação e a análise espacial de dados agrometeorológicos com aplicação em estudos de diferentes escalas de produção agropecuária.","kind":"conceito","status":"confirmado","as_of":"2014","edition_number":null,"edition_year":null,"dynamic_instructions":null,"citation_template":null,"sources":[{"title":"Embrapa – Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2014), pergunta 195","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/988805/1/500P-Geotecnologias-e-geoinformacao-ed01-2014.pdf","accessed":"2026-10-17","publisher":"Embrapa","item":195,"label":"Embrapa – Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2014), pergunta 195"},{"title":"Infoteca-e Embrapa – registro do livro \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\"","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/handle/doc/988805","accessed":"2026-10-17","label":"Infoteca-e Embrapa – registro do livro \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\""}],"tags":["geo","geotecnologias e agricultura de precisão"],"related_ids":["AGTECH-GEO-0196"],"fenasoja_links":[],"gaps":[],"relevance":"media","priority":2,"kb_version":"2026-10-17","context":{"scope":"general","subject":"agriculture","reference_period":null,"valid_from":null,"valid_until":null,"edition_required":false},"public_notes":["Referência: publicação da Embrapa de 2014. Informações técnicas, produtos, cultivares e números podem estar desatualizados."],"query_policy":{"collision_groups":[],"preference_rank":1},"editorial_metadata":{"area":"AGTECH","area_nome":"Inovação e agtech","subcategoria":"Geotecnologias e agricultura de precisão","interpretation_notes":"Resposta resumida do item nº 195 do livro da Embrapa \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\" (2014).","kind":"conceito","status":"confirmado","as_of":"2014","relevancia_fenasoja":"média","fenasoja_kb_links":[],"n_perguntas":4,"fonte_tipo":"Embrapa – Coleção 500 Perguntas 500 Respostas"},"provenance":{"source_file":"kb-expandida.json","source_sha256":"326121e0e7d4c5ef3b6dcd2ffcbb438122b02c82f39881f01f8940a2190d1f36","source_entry_id":"AGTECH-GEO-0195","revision":"2026-10-17","managed_by":"fenasoja-kb-seed"},"managed_by":"fenasoja-kb-seed"}'::jsonb),
('{"id":"AGTECH-GEO-0196","kb":"expandida","area":"AGTECH","area_name":"Inovação e agtech","subcategory":"Geotecnologias e agricultura de precisão","canonical_question":"Geotecnologias: como é utilizada a informação obtida?","answer":"Dispondo-se de computadores, de programas específicos e de imagens de satélite, é possível por em prática uma série de procedimentos para processar essas informações e assim obter dados georreferenciados, que permitem localizar as áreas de estudo de maneira fidedigna.","kind":"conceito","status":"confirmado","as_of":"2014","edition_number":null,"edition_year":null,"dynamic_instructions":null,"citation_template":null,"sources":[{"title":"Embrapa – Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2014), pergunta 196","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/988805/1/500P-Geotecnologias-e-geoinformacao-ed01-2014.pdf","accessed":"2026-10-17","publisher":"Embrapa","item":196,"label":"Embrapa – Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2014), pergunta 196"},{"title":"Infoteca-e Embrapa – registro do livro \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\"","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/handle/doc/988805","accessed":"2026-10-17","label":"Infoteca-e Embrapa – registro do livro \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\""}],"tags":["geo","geotecnologias e agricultura de precisão"],"related_ids":["AGTECH-GEO-0195"],"fenasoja_links":[],"gaps":[],"relevance":"media","priority":2,"kb_version":"2026-10-17","context":{"scope":"general","subject":"agriculture","reference_period":null,"valid_from":null,"valid_until":null,"edition_required":false},"public_notes":["Referência: publicação da Embrapa de 2014. Informações técnicas, produtos, cultivares e números podem estar desatualizados."],"query_policy":{"collision_grou