INSERT INTO _kb_seed_entries(payload) VALUES
('{"id":"AGTECH-GEO-0396","kb":"expandida","area":"AGTECH","area_name":"Inovação e agtech","subcategory":"Geotecnologias e agricultura de precisão","canonical_question":"Geotecnologias: o que é Cadastro Ambiental Rural (CAR)?","answer":"É o cadastramento da propriedade rural via internet, na página do Ministério do Meio Ambiente, sendo um dos desdobramentos do novo Código Florestal Brasileiro e promove a regularização ambiental de imóveis rurais. Foi institucionalizado em âmbito nacional, determinando sua obrigatoriedade conforme dispõe a Lei nº 12.651, de 25 de maio de 2012 (BRASIL, 2012b), artigo 29, e regulamentado pelo Decreto nº 7.830, de 17 de outubro de 2012 (BRASIL, 2012a). O governo federal repassou para os estados e municípios a responsabilidade de executar o Cadastro dos Imóveis Rurais, todos georreferenciados. Algumas Unidades da Federação já possuíam sistemas próprios de cadastros de imóveis rurais.","kind":"conceito","status":"confirmado","as_of":"2014","edition_number":null,"edition_year":null,"dynamic_instructions":null,"citation_template":null,"sources":[{"title":"Embrapa – Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2014), pergunta 396","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/988805/1/500P-Geotecnologias-e-geoinformacao-ed01-2014.pdf","accessed":"2026-10-17","publisher":"Embrapa","item":396,"label":"Embrapa – Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2014), pergunta 396"},{"title":"Infoteca-e Embrapa – registro do livro \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\"","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/handle/doc/988805","accessed":"2026-10-17","label":"Infoteca-e Embrapa – registro do livro \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\""}],"tags":["geo","geotecnologias e agricultura de precisão"],"related_ids":["AGTECH-GEO-0395","AGTECH-GEO-0397"],"fenasoja_links":[],"gaps":[],"relevance":"media","priority":2,"kb_version":"2026-10-17","context":{"scope":"general","subject":"agriculture","reference_period":null,"valid_from":null,"valid_until":null,"edition_required":false},"public_notes":["Referência: publicação da Embrapa de 2014. Informações técnicas, produtos, cultivares e números podem estar desatualizados."],"query_policy":{"collision_groups":[],"preference_rank":1},"editorial_metadata":{"area":"AGTECH","area_nome":"Inovação e agtech","subcategoria":"Geotecnologias e agricultura de precisão","interpretation_notes":"Resposta resumida do item nº 396 do livro da Embrapa \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\" (2014). Pergunta original do livro sem menção explícita ao tema; prefixo \"Geotecnologias\" adicionado para dar contexto.","kind":"conceito","status":"confirmado","as_of":"2014","relevancia_fenasoja":"média","fenasoja_kb_links":[],"n_perguntas":4,"fonte_tipo":"Embrapa – Coleção 500 Perguntas 500 Respostas"},"provenance":{"source_file":"kb-expandida.json","source_sha256":"326121e0e7d4c5ef3b6dcd2ffcbb438122b02c82f39881f01f8940a2190d1f36","source_entry_id":"AGTECH-GEO-0396","revision":"2026-10-17","managed_by":"fenasoja-kb-seed"},"managed_by":"fenasoja-kb-seed"}'::jsonb),
('{"id":"AGTECH-GEO-0397","kb":"expandida","area":"AGTECH","area_name":"Inovação e agtech","subcategory":"Geotecnologias e agricultura de precisão","canonical_question":"Geotecnologias: o que é Sistema de Cadastro Ambiental Rural (SiCAR)?","answer":"É o sistema informatizado ou ferramenta eletrônica que recebe, gerencia e integra os dados do CAR de todas as Unidades da Federação, desenvolvido pelo Ministério do Meio Ambiente (MMA) e criado pelo Decreto nº 7.830, de 17 de outubro de 2012 (BRASIL, 2012a), para armazenar as informações georreferenciadas e características das propriedades rurais (localização, perímetro, áreas de vegetação nativa, áreas de preservação permanente (APP), área de reserva legal (RL) e de uso restrito inscritas ou cadastradas no CAR.","kind":"conceito","status":"confirmado","as_of":"2014","edition_number":null,"edition_year":null,"dynamic_instructions":null,"citation_template":null,"sources":[{"title":"Embrapa – Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2014), pergunta 397","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/988805/1/500P-Geotecnologias-e-geoinformacao-ed01-2014.pdf","accessed":"2026-10-17","publisher":"Embrapa","item":397,"label":"Embrapa – Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde (Coleção 500 Perguntas 500 Respostas, 2014), pergunta 397"},{"title":"Infoteca-e Embrapa – registro do livro \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\"","url":"https://www.infoteca.cnptia.embrapa.br/infoteca/handle/doc/988805","accessed":"2026-10-17","label":"Infoteca-e Embrapa – registro do livro \"Geotecnologias e geoinformação: o produtor pergunta, a Embrapa responde\""}],"tags":["geo","geotecnologias e agricultura de precisão"],"related_ids":["AGTECH-GEO-0396"],"fenasoja_links":[],"gaps":[],"relevance":"media","priority":2,"kb_version":"2026-10-17","context":{"scope":"general","subject":"agricultur