vas (\"aproximadamente\"). ","entities":{"edition_number":24,"edition_year":2024}},"provenance":{"source_file":"fenasoja-kb.json","source_sha256":"1bce6b6077c391c22ba2c56c96ea855af29ad546c0ba538674eb30d3768232a6","source_entry_id":"ED24-PUB","revision":"2026-10-17","managed_by":"fenasoja-kb-seed"},"managed_by":"fenasoja-kb-seed"}'::jsonb),
