('{"id":"FAQ-SF-002","kb":"expandida","area":"FAQ","area_name":"FAQ do visitante","subcategory":"Regras do parque","canonical_question":"Onde fica o achados e perdidos da Fenasoja?","answer":"SEM FONTE CONFIRMADA. As fontes consultadas não informam o local de achados e perdidos. O visitante deve procurar a administração do parque ou os contatos oficiais da organização.","kind":"orientacao","status":"sem_fonte","as_of":null,"edition_number":null,"edition_year":null,"dynamic_instructions":null,"citation_template":null,"sources":[{"title":"Fenasoja – Contato","url":"https://fenasoja.com.br/contato/","accessed":"2026-10-17","note":"fonte da KB Fenasoja (já consultada)","label":"Fenasoja – Contato"}],"tags":["achados e perdidos"],"related_ids":[],"fenasoja_links":["VIS-005"],"gaps":["Local de achados e perdidos não localizado."],"relevance":"media","priority":2,"kb_version":"2026-10-17","context":{"scope":"general","subject":"fenasoja","reference_period":null,"valid_from":null,"valid_until":null,"edition_required":false},"public_notes":[],"query_policy":{"collision_groups":[],"preference_rank":1},"editorial_metadata":{"area":"FAQ","area_nome":"FAQ do visitante","subcategoria":"Regras do parque","interpretation_notes":"","kind":"orientação","status":"sem_fonte","as_of":null,"relevancia_fenasoja":"média","fenasoja_kb_links":["VIS-005"],"n_perguntas":5,"fonte_tipo":"Curadoria manual sobre fontes oficiais"},"provenance":{"source_file":"kb-expandida.json","source_sha256":"326121e0e7d4c5ef3b6dcd2ffcbb438122b02c82f39881f01f8940a2190d1f36","source_entry_id":"FAQ-SF-002","revision":"2026-10-17","managed_by":"fenasoja-kb-seed"},"managed_by":"fenasoja-kb-seed"}'::jsonb),
